import{_ as t,o as e,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const u=JSON.parse('{"title":"设计趋势 - 2026-07-05","description":"","frontmatter":{"date":"2026-07-05T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-05-uxtrend.md","filePath":"daily/2026-07-05-uxtrend.md"}'),o={name:"daily/2026-07-05-uxtrend.md"};function s(i,r,g,p,h,l){return e(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="设计趋势-2026-07-05" tabindex="-1">设计趋势 - 2026-07-05 <a class="header-anchor" href="#设计趋势-2026-07-05" aria-label="Permalink to &quot;设计趋势 - 2026-07-05&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于代理型用户体验（代理UX）和AI在设计工作流程中的应用。主要动态包括探讨代理UX设计原则、光标和Manus等工具的AI集成，以及代理型UX对设计认知的影响。最值得关注的是光标、氛围编码和Manus工具的用户体验革命，以及代理式UX的7个设计原则，这些将推动人机交互向更自然、目标导向的方向发展。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨设计新型数字设备用户体验的代理UX设计原则。</p><p><strong>能解决什么问题</strong>: 解决数字设备中代理系统用户体验设计的独特挑战。</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速智能代理系统开发。</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划和情绪管理。</p><hr><h3 id="_2-光标、氛围编码和manus-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和Manus：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和manus-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和Manus：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor和Manus等工具将AI直接嵌入工作流程，实现更自然、目标导向的交互。</p><p><strong>能解决什么问题</strong>: 解决传统编程环境中与AI交互复杂、低效的问题。</p><p><strong>产品应用</strong>: 可以应用于开发环境，提高编程效率和用户体验。</p><p><strong>示例场景</strong>: 开发者通过Cursor直接与AI对话，优化代码。</p><hr><h3 id="_3-为什么代理型ux将改变你对设计的所有认知" tabindex="-1">3. 为什么代理型UX将改变你对设计的所有认知 <a class="header-anchor" href="#_3-为什么代理型ux将改变你对设计的所有认知" aria-label="Permalink to &quot;3. 为什么代理型UX将改变你对设计的所有认知&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理型UX设计关注于人机间的信任协调，而非界面和功能。</p><p><strong>能解决什么问题</strong>: 如何让用户接受、信任并有效利用AI代理。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，通过设计确保用户感到被支持和控制。</p><p><strong>示例场景</strong>: 金融代理提示可疑交易，但需人工批准才能冻结账户。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D | Binome | Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，强调工作流作为任务协调器的角色。</p><p><strong>能解决什么问题</strong>: 解决如何使AI代理更有效地规划、执行任务并模拟人类推理的问题。</p><p><strong>产品应用</strong>: 可以应用于实际产品，通过设计灵活的工作流来处理不同的问题。</p><p><strong>示例场景</strong>: 利用ReAct模式，结合工具增强AI代理的能力。</p><hr><h3 id="_5-代理式ux-设计代理系统的7个原则" tabindex="-1">5. 代理式UX：设计代理系统的7个原则 <a class="header-anchor" href="#_5-代理式ux-设计代理系统的7个原则" aria-label="Permalink to &quot;5. 代理式UX：设计代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时，应确保上下文双向流动，增强智能行为的可信度。</p><p><strong>能解决什么问题</strong>: 解决代理行为与用户工作流程脱节，缺乏上下文感知的问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助完成工作的系统，如自动化客服、任务分配等。</p><p><strong>示例场景</strong>: 智能助手在用户工作界面中直接提供信息和建议，无需切换模式。</p><hr><h3 id="_6-ai在设计中的应用-改变我们的创造方式" tabindex="-1">6. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_6-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;6. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create | Figma</a></p><p><strong>一句话摘要</strong>: AI正深入设计流程，提升工作效率和个性化体验。</p><p><strong>能解决什么问题</strong>: 解决设计任务自动化和个性化界面创建的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI提升设计效率和用户体验。</p><p><strong>示例场景</strong>: 使用AI设计工具为不同用户定制个性化界面。</p><hr><h3 id="_7-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">7. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_7-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;7. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI功能</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人提供问题提示和操作指导</p><hr><h3 id="_8-ai-ux设计模式-人工智能带来的新体验" tabindex="-1">8. AI UX设计模式：人工智能带来的新体验 <a class="header-anchor" href="#_8-ai-ux设计模式-人工智能带来的新体验" aria-label="Permalink to &quot;8. AI UX设计模式：人工智能带来的新体验&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: AI UX设计模式旨在整理和简化AI体验中的关键交互模式。</p><p><strong>能解决什么问题</strong>: 帮助设计师在涉及AI的产品设计中做出更好的UX决策。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过评估选择最适合的模式。</p><p><strong>示例场景</strong>: 使用AI UX模式设计一个智能助手的交互界面。</p><hr><h3 id="_9-在cursor中使用ai可读设计系统进行设计" tabindex="-1">9. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_9-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;9. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: AI直接根据产品需求和UX规范生成完整产品流程。</p><p><strong>能解决什么问题</strong>: 提高设计效率，确保设计遵循统一的设计系统。</p><p><strong>产品应用</strong>: 适用于需要快速原型制作和设计系统一致性的产品开发。</p><p><strong>示例场景</strong>: 设计师使用现有网站截图生成符合设计系统的原型。</p><hr><h3 id="_10-为代理式用户体验设计-—-指南" tabindex="-1">10. 为代理式用户体验设计 — 指南 <a class="header-anchor" href="#_10-为代理式用户体验设计-—-指南" aria-label="Permalink to &quot;10. 为代理式用户体验设计 — 指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理式用户体验，预测并满足用户未知需求。</p><p><strong>能解决什么问题</strong>: 解决用户在海量信息中发现潜在兴趣点的问题。</p><p><strong>产品应用</strong>: 可应用于个性化推荐系统，通过算法分析用户数据，预测用户需求。</p><p><strong>示例场景</strong>: 智能助手根据用户行为推荐可能感兴趣的新闻。</p><hr>',75)])])}const c=t(o,[["render",s]]);export{u as __pageData,c as default};
